// Un thème : la palette complète d'une apparence de KDX (voir THEME_GROUPS dans gen/gen_tokens.py). light : texte sombre sur fond clair.
struct Theme {
    const char* id;
    const char* nom;
    bool light;
    unsigned frame, panel, btn, btnHover, card2, ink, colA, colB, head, sbTrack, sbBtn, sbThumb, hl;  // Surfaces
    unsigned text, faint, btnText, headText, listText, titleText, tbText, hlText, fieldInk, ownInk, sbArrow;  // Texte
    unsigned outline, outlineActive, btnOutline, fieldOutline, line, hi, hi2, lo, lo2, fieldHi, fieldLo, rowHover, rowSel, rowSelRing;  // Contours et reliefs
    unsigned tbEdge, tbMid, tbLow, tbFrom, tbGradMid, tbTo;  // Cadre inactif
    unsigned aEdge, aMid, aDark, aHover, aTitleFrom, aTitleMid, aTitleTo, barTop, barMid, barBot, aSpark, accent, icAccent, icAccentDark, defOutline, defEdge, defMid;  // Cadre actif et accent
    unsigned selBg, selFg;  // Sélection
};

